INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1317681-ee411', 'stk-ee-220', 'EE 411', 'info', '{"desc": "السلام عليكم …\nياشباب السينيربروجكت حق الساينس 3 كريدتس و الابلايد نفس الكلام …\nلكن في الساينس في 6 ساعات لاب و ساعه ليكتشر بالاسبوع , وش نظامها هذي ؟ الطلاب يجتمعون لحالهم ولا يكون فيه دكتور باللاب ؟\nوهل مواضيع الساينس تختلف عن مواضيع الابلايد ؟\nمشكورين …واي معلومات عن اختيار فريق العمل و الدكتور و الامور هذي ؟\nوهل هو ينزل الترم الأول و الثاني ؟\nشكراً …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-411-senior-design-project/120706/2", "user": "EE-220", "ts": 1389261272000, "tid": 120706, "pn": 2}}', 1389261272000, 1794826858, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1317910-ee411', 'stk-_prince', 'EE 411', 'info', '{"desc": "السلام عليكم …\n\nعليكم السلام\n\nياشباب السينيربروجكت حق الساينس 3 كريدتس و الابلايد نفس الكلام …\nلكن في الساينس في 6 ساعات لاب و ساعه ليكتشر بالاسبوع , وش نظامها هذي ؟ الطلاب يجتمعون لحالهم ولا يكون فيه دكتور باللاب ؟\n\nفي العادة القروب يحدد يوم للقاء الدكتور كل اسبوع ليتابع عملهم ويجاوب الاسئلة (مو شرط يكون نفس المسجل )\nوالباقي على القروب ينسقون مع بعضهم\n\nوهل مواضيع الساينس تختلف عن مواضيع الابلايد ؟\n\nنفس المواضيع تكون …طلاب الساينس يقدروا يصيروا مع الابلايد في قروب\n\nمشكورين …واي معلومات عن اختيار فريق العمل و الدكتور و الامور هذي ؟\n\nاختيار فريق العمل صراحة من قبل كان افضل ان كل قروب يقدموا اوراقهم سوا بعد معرفة بروجكت كل دكتور\nاما الحين فالوضع\"من سبق لبق\"الي يصيد السكشن يصير فيه\nيعني احتمال كبير انك ماتصير مع قروبك اللي متفق معاه اذا ماصدتوا نفس السكشن\n\nوهل هو ينزل الترم الأول و الثاني ؟\nشكراً …\n\nينزل الترمين 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-411-senior-design-project/120706/3", "user": "_PrInCe", "ts": 1389314545000, "tid": 120706, "pn": 3}}', 1389314545000, 1794826858, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p292906-ee411', 'stk-user1091', 'EE 411', 'info', '{"desc": "وعليكم السلام\n\nبالنسبة للمادة 411 قبل الكواب ما عندي خبر\n\nبس اللي اعرفه لازم تكون سينير حتى تاخذها\n\nوالمدرس اللي نزلت عنده المادة في الريجسترار مو شرط هو اللي بيمسك البروجكت معاك\nهذا حاطينه حتى يشرح لك في أول الأسابيع بعض الأشياء في الكورس وبعد كذا ما يدري عنك\n\nأنا اقترح تشوف لك قروب من الحين قبل بداية السمستر وتتفقون مع مدرس ممتاز وتروحون تكلمونه إنكم تبغون تصيرون معاه في بروجكت هو يختاره أو انتم تختارونه\n\nوإذا ما اخترت الدكتور ولا القروب فالقسم بيحط لك دكتور وقروب وبروجكت من عنده", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee411/65031/2", "user": "user1091", "ts": 1217406227000, "tid": 65031, "pn": 2}}', 1217406227000, 1794826858, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1468538-ee411', 'stk-alasad', 'EE 411', 'srcU', '{"html": "&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt;<br>هذي الملفات الي لقيتها طبعا مافي سلبس موحد لجميع السكاشن<br>ان شاء من تاخد عند دكتور بوضح لك اكثر لان من دكتور لدكتور الوضع يختلف قليل<br><br>​<span data-fid=\"stk-f1468538-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1468538-0": {"name": "RE__Capstone_Meeting.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/836c04b38ad0858a055d96ec0af85529bee2d4f13828a8c77cedb5e19a791b0d"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/senior-project-ee411/176082/4", "user": "alasad", "ts": 1487377044000, "tid": 176082, "pn": 4}}', 1487377044000, 1794826858, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
